// ═══════════════════════════════════════════════════════════════
//  DUNGEON LEGENDS — ВСЁ В ОДНОМ ФАЙЛЕ (сервер + игра + общая база)
//
//  Что делает: раздаёт игру по адресу сайта и хранит общие данные
//  (рынок, PvP, Глобальный Босс) в Postgres.
//
//  КАК ЗАПУСТИТЬ (хватит одного этого файла в репозитории GitHub):
//   1. Положите этот файл в репозиторий GitHub под именем server.js
//   2. Render → New → PostgreSQL (создать базу), скопируйте Internal Database URL
//   3. Render → New → Web Service → выберите репозиторий, настройки:
//        Runtime:        Node
//        Build Command:  npm install express pg cors
//        Start Command:  node server.js
//        Environment:    DATABASE_URL = <Internal Database URL из шага 2>
//   4. Откройте адрес сервиса (https://имя.onrender.com) — игра там.
//
//  Игра внутри файла закодирована (base64) в самом низу — править её тут не нужно.
// ═══════════════════════════════════════════════════════════════
const express = require('express');
const cors = require('cors');

const MAX_KEY = 200;
const MAX_VALUE = 200 * 1024;      // 200 КБ на значение
const MAX_LIST = 1000;
const KEY_RE = /^[^\s/\\'"]+$/;     // без пробелов, слэшей, кавычек
const RATE_LIMIT = 240;            // запросов в минуту с одного IP

function createApp(pool) {
  const app = express();
  app.set('trust proxy', 1);
  app.use(cors());
  app.use(express.json({ limit: '300kb' }));

  const hits = new Map();
  setInterval(() => hits.clear(), 60 * 1000).unref();
  app.use('/api', (req, res, next) => {
    const ip = req.ip || 'x';
    const n = (hits.get(ip) || 0) + 1;
    hits.set(ip, n);
    if (n > RATE_LIMIT) return res.status(429).json({ error: 'rate_limited' });
    next();
  });

  const ns = (req, shared) => {
    if (shared) return 'shared';
    const id = String(req.get('X-Client-Id') || '').slice(0, 64);
    return /^[A-Za-z0-9_-]{8,64}$/.test(id) ? 'u:' + id : null;
  };
  const isShared = (v) => v === true || v === 1 || v === '1' || v === 'true';
  const validKey = (k) => typeof k === 'string' && k.length > 0 && k.length <= MAX_KEY && KEY_RE.test(k);
  const bad = (res, msg) => res.status(400).json({ error: msg });

  app.get('/api/health', async (req, res) => {
    try { await pool.query('SELECT 1'); res.json({ ok: true }); }
    catch (e) { res.status(500).json({ ok: false }); }
  });

  app.get('/api/get', async (req, res) => {
    const shared = isShared(req.query.shared), key = req.query.key, space = ns(req, shared);
    if (!validKey(key)) return bad(res, 'bad_key');
    if (!space) return bad(res, 'bad_client');
    try {
      const r = await pool.query('SELECT value FROM kv WHERE ns=$1 AND key=$2', [space, key]);
      if (!r.rows.length) return res.status(404).json({ error: 'not_found' });
      res.json({ key, value: r.rows[0].value, shared });
    } catch (e) { console.error(e); res.status(500).json({ error: 'db' }); }
  });

  app.post('/api/set', async (req, res) => {
    const { key, value } = req.body || {};
    const shared = isShared(req.body && req.body.shared), space = ns(req, shared);
    if (!validKey(key)) return bad(res, 'bad_key');
    if (typeof value !== 'string' || value.length > MAX_VALUE) return bad(res, 'bad_value');
    if (!space) return bad(res, 'bad_client');
    try {
      await pool.query(
        `INSERT INTO kv (ns, key, value, updated_at) VALUES ($1,$2,$3,now())
         ON CONFLICT (ns, key) DO UPDATE SET value=EXCLUDED.value, updated_at=now()`,
        [space, key, value]);
      res.json({ key, value, shared });
    } catch (e) { console.error(e); res.status(500).json({ error: 'db' }); }
  });

  app.post('/api/delete', async (req, res) => {
    const { key } = req.body || {};
    const shared = isShared(req.body && req.body.shared), space = ns(req, shared);
    if (!validKey(key)) return bad(res, 'bad_key');
    if (!space) return bad(res, 'bad_client');
    try {
      const r = await pool.query('DELETE FROM kv WHERE ns=$1 AND key=$2', [space, key]);
      res.json({ key, deleted: r.rowCount > 0, shared });
    } catch (e) { console.error(e); res.status(500).json({ error: 'db' }); }
  });

  app.get('/api/list', async (req, res) => {
    const shared = isShared(req.query.shared), space = ns(req, shared);
    const prefix = typeof req.query.prefix === 'string' ? req.query.prefix.slice(0, MAX_KEY) : '';
    if (!space) return bad(res, 'bad_client');
    try {
      const r = await pool.query('SELECT key FROM kv WHERE ns=$1 ORDER BY key LIMIT 20000', [space]);
      const keys = r.rows.map((x) => x.key).filter((k) => k.startsWith(prefix)).slice(0, MAX_LIST);
      res.json({ keys, prefix, shared });
    } catch (e) { console.error(e); res.status(500).json({ error: 'db' }); }
  });

  // сама игра
  const HTML = Buffer.from(HTML_B64.join(''), 'base64');
  app.get(['/', '/index.html'], (req, res) => {
    res.set('Cache-Control', 'no-cache');
    res.type('html').send(HTML);
  });
  return app;
}

async function initDb(pool) {
  await pool.query(`CREATE TABLE IF NOT EXISTS kv (
    ns TEXT NOT NULL,
    key TEXT NOT NULL,
    value TEXT NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (ns, key)
  )`);
}

module.exports = { createApp, initDb };

if (require.main === module) {
  const { Pool } = require('pg');
  if (!process.env.DATABASE_URL) { console.error('Нет переменной DATABASE_URL'); process.exit(1); }
  const pool = new Pool({
    connectionString: process.env.DATABASE_URL,
    // внешний адрес Render требует SSL; внутренний — нет
    ssl: /render\.com/.test(process.env.DATABASE_URL) ? { rejectUnauthorized: false } : undefined,
  });
  initDb(pool).then(() => {
    const port = process.env.PORT || 3000;
    createApp(pool).listen(port, () => console.log('Dungeon Legends on :' + port));
  }).catch((e) => { console.error(e); process.exit(1); });
}

